import { renderMap } from './location-map.js';
const card=document.querySelector('[data-live-location]');
if(card){
  const select=card.querySelector('select'),button=card.querySelector('[data-location-toggle]'),status=card.querySelector('[data-location-status]'),legend=card.querySelector('[data-location-people]');
  let watch=null,session=null,snapshot={people:[]},sending=false,lastSent=0,busy=false;
  select.value=localStorage.getItem('location-actor')||'';
  const api=async body=>{const r=await fetch('/api/location',{method:body?'POST':'GET',headers:{Accept:'application/json',...(body?{'Content-Type':'application/json','X-Asechka-Location':'1'}:{})},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store'});const v=await r.json();if(!r.ok)throw new Error(v.error||'Location needs a moment.');return v;};
  function paint(){button.textContent=session?'Stop sharing':'Share location';button.disabled=busy||(!session&&!select.value);select.disabled=!!session||busy;legend.replaceChildren(...['asnat','youssef'].map(actor=>{const p=snapshot.people.find(p=>p.actor===actor),span=document.createElement('span');const age=p?.position?Math.max(0,Math.floor((Date.now()-p.position.capturedAt)/1000)):null;span.textContent=(actor==='asnat'?'Asnat':'Youssef')+' · '+(age!==null?(age>300?'No recent location':age<60?'Live · ±'+p.position.accuracy+' m':Math.floor(age/60)+'m ago · paused'):p?.sharing?'Waiting for GPS':'Not sharing');return span;}));renderMap(card.querySelector('[data-location-map]'),snapshot.people);}
  async function refresh(){if(document.hidden)return;try{snapshot=await api();paint();}catch(e){status.textContent=e.message;}}
  function pause(){if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null;}}
  function observe(){if(!session||document.hidden||watch!==null)return;watch=navigator.geolocation.watchPosition(async p=>{if(sending||Date.now()-lastSent<8000||!session)return;sending=true;lastSent=Date.now();try{snapshot=await api({action:'update',...session,position:{latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,capturedAt:Math.round(p.timestamp)}});status.textContent='Sharing while this page is open. Use the phone app for background updates.';paint();}catch(e){status.textContent=e.message;}finally{sending=false;}},()=>{status.textContent='Location unavailable. Allow location permission and check your signal.';},{enableHighAccuracy:true,maximumAge:0,timeout:20000});}
  select.onchange=()=>{localStorage.setItem('location-actor',select.value);paint();};
  button.onclick=async()=>{if(busy)return;if(!session&&!confirm('Share your current location with your partner? This page updates while open. Stop anytime; use the app to share in the background.'))return;busy=true;paint();try{if(session){pause();snapshot=await api({action:'stop',...session});session=null;status.textContent='Location sharing is off.';}else{if(!navigator.geolocation)throw new Error('This browser does not support location.');const v=await api({action:'start',actor:select.value});session={actor:select.value,token:v.token};snapshot=v;status.textContent='Waiting for location permission…';observe();}paint();}catch(e){status.textContent=e.message;}finally{busy=false;paint();}};
  document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();else{observe();refresh();}});
  window.addEventListener('pagehide',()=>{pause();if(session){fetch('/api/location',{method:'POST',headers:{'Content-Type':'application/json','X-Asechka-Location':'1'},body:JSON.stringify({action:'stop',...session}),keepalive:true}).catch(()=>{});}});
  setInterval(refresh,10000);setInterval(paint,10000);paint();refresh();
}
